const slug = (value) => value.normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

const RANK = new Map(WORDS.map((word, i) => [word, i]));

const bandOf = (rank) => BANDS.find((band) => rank >= band.from && rank < band.to).id;

/** Two sentences per row, each a card of its own. */
export const SENTENCES = RAW.flatMap(([word, ...pairs]) => {
  const rank = RANK.get(word);
  if (rank === undefined) throw new Error(`not in the word list: ${word}`);
  return [0, 2].map((i) => ({
    word,
    rank,
    band: bandOf(rank),
    fr: pairs[i],
    en: pairs[i + 1],
    id: slug(pairs[i]),
  }));
});

export const SENTENCE_BY_ID = new Map(SENTENCES.map((sentence) => [sentence.id, sentence]));

export const sentencesForBands = (bands) =>
  SENTENCES.filter((sentence) => bands.includes(sentence.band));
